import pandas as pd
from itertools import combinations

def token_overlap(a, b):
    ta = set(a.lower().split(' | '))
    tb = set(b.lower().split(' | '))
    if not ta or not tb:
        return 0.0
    return len(ta & tb) / min(len(ta), len(tb))

full_df = pd.read_csv('/root/output/unified_taxonomy_full.csv')
violations = []
for l1, group in full_df.groupby('unified_level_1'):
    cats = sorted([c for c in group['unified_level_2'].dropna().unique() if c])
    for a, b in combinations(cats, 2):
        if token_overlap(a, b) >= 0.3:
            violations.append((l1, a, b, token_overlap(a, b)))
            break

print('violations', len(violations))
print(violations[:10])
PY"}
